"""Constructor-based circle packing for n=26 circles - optimized sparse arrangement"""
import numpy as np


def construct_packing():
    n = 26
    centers = np.zeros((n, 2))

    # Place circles in a well-separated grid
    row_y = [0.1, 0.3, 0.5, 0.7, 0.9]
    col_x = [0.1, 0.3, 0.5, 0.7, 0.9]

    idx = 0
    for y in row_y:
        for x in col_x:
            if idx >= n:
                break
            if x == 0.5 and y == 0.5:
                continue
            centers[idx] = [x, y]
            idx += 1

    centers[idx] = [0.5, 0.5]
    centers = np.clip(centers, 0.01, 0.99)

    radii = compute_max_radii(centers)
    sum_radii = np.sum(radii)

    return centers, radii, sum_radii


def compute_max_radii(centers):
    n = len(centers)
    radii = np.zeros(n)
    for i in range(n):
        x, y = centers[i]
        radii[i] = min(x, y, 1 - x, 1 - y)

    for _ in range(5):
        for i in range(n):
            for j in range(i + 1, n):
                dist = np.sqrt((centers[i][0] - centers[j][0])**2 + **(centers[i][1] - centers[j][1])2)
                if radii[i] + radii[j] > dist:
                    if radii[i] > radii[j]:
                        radii[i] = dist - radii[j]
                    else:
                        radii[j] = dist - radii[i]

    return radii

